// App ↔ database mapping. Database IDs and auth UUIDs are never generated by the UI.
export function taskFromRow(row) {
  const due = row.due_date ? new Date(row.due_date) : null;
  const date = due && !Number.isNaN(due.getTime())
    ? `${due.getFullYear()}-${String(due.getMonth() + 1).padStart(2, '0')}-${String(due.getDate()).padStart(2, '0')}`
    : '';
  return {
    id: String(row.id), title: row.title, date,
    time: date ? `${String(due.getHours()).padStart(2, '0')}:${String(due.getMinutes()).padStart(2, '0')}` : '',
    category: row.category || 'Study', priority: row.priority || 'Medium',
    done: row.is_completed, group_id: row.group_id == null ? null : String(row.group_id),
    assigned_to: row.assigned_to, user_id: row.user_id, persisted: true,
  };
}

export function taskToRow(form, userId) {
  const due = new Date(`${form.date}T${form.time}:00`);
  if (Number.isNaN(due.getTime())) throw new Error('วันหรือเวลาไม่ถูกต้อง');
  return {
    title: form.title.trim(), due_date: due.toISOString(),
    category: form.category, priority: form.priority,
    is_completed: Boolean(form.done), user_id: userId,
    group_id: form.group_id || null, assigned_to: form.assigned_to || null,
  };
}

export function databaseMessage(error) {
  if (error?.code === 'PGRST202' || /could not find the function/i.test(error?.message || '')) return 'กรุณารัน supabase/setup-groups.sql ใน SQL Editor แล้วกดโหลดใหม่';
  if (error?.code === '42501' && /สมาชิกกลุ่ม/.test(error?.message || '')) return error.message;
  if (error?.code === '42501' || /row.level security|permission denied/i.test(error?.message || '')) {
    return 'Supabase ยังไม่อนุญาตให้บันทึกข้อมูล กรุณารัน supabase/setup-tasks.sql ใน SQL Editor ก่อน';
  }
  if (error?.code === '23503') return 'ไม่พบโปรไฟล์ของบัญชีนี้ กรุณาออกจากระบบแล้วเข้าสู่ระบบใหม่';
  return error?.message || 'ติดต่อ Supabase ไม่สำเร็จ กรุณาลองใหม่';
}

export function createTaskRepository(client) {
  return {
    async list() {
      const { data, error } = await client.from('tasks').select('*')
        .order('created_at', { ascending: false });
      if (error) throw error;
      return data.map(taskFromRow);
    },
    async save(form, userId) {
      const row = taskToRow(form, userId);
      if (form.group_id) {
        const { data, error } = await client.rpc('donee_save_group_task', {
          p_group_id: form.group_id, p_task_id: form.persisted ? form.id : null,
          p_title: row.title, p_due_date: row.due_date, p_category: row.category,
          p_priority: row.priority, p_completed: row.is_completed,
        });
        if (error) throw error;
        return taskFromRow(data);
      }
      row.assigned_to = null;
      let query = form.persisted
        ? client.from('tasks').update(row).eq('id', form.id).eq('user_id', userId).is('group_id', null)
        : client.from('tasks').insert(row);
      const { data, error } = await query.select('*').single();
      if (error) throw error;
      return taskFromRow(data);
    },
    async complete(task, userId) {
      if (task.group_id) {
        const { data, error } = await client.rpc('donee_complete_group_task', {
          p_group_id: task.group_id, p_task_id: task.id, p_completed: !task.done,
        });
        if (error) throw error;
        return taskFromRow(data);
      }
      const { data, error } = await client.from('tasks').update({ is_completed: !task.done })
        .eq('id', task.id).eq('user_id', userId).is('group_id', null).select('*').single();
      if (error) throw error;
      return taskFromRow(data);
    },
    async remove(taskId, userId, groupId = null) {
      if (groupId) {
        const { error } = await client.rpc('donee_delete_group_task', { p_group_id: groupId, p_task_id: taskId });
        if (error) throw error;
        return;
      }
      const { data, error } = await client.from('tasks').delete()
        .eq('id', taskId).eq('user_id', userId).is('group_id', null).select('id');
      if (error) throw error;
      if (!data?.length) throw new Error('ลบงานไม่สำเร็จ: งานอาจถูกลบแล้วหรือบัญชีนี้ไม่มีสิทธิ์ กรุณากดโหลดใหม่');
    },
  };
}
